    enonce: "بيّن أنّ:<br><span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">1 - n<sup>2</sup></span><span class=\"den\">n</span></span> &lt; <span class=\"frac\"><span class=\"num\">1 - m<sup>2</sup></span><span class=\"den\">m</span></span></span>",
